#!/usr/bin/env python3
from __future__ import annotations
import argparse,hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.tfg_phase0.mapillary_visual_pilot import reject_ground_truth
from src.tfg_phase0.visual_reranking import canonical_bytes,compile_atomic_claims,plan_multiview_associations
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser(description='Prepara fixture visual genérica desde ranking CT2L congelado');p.add_argument('--query-id',required=True);p.add_argument('--kind',default='en_cartographic');p.add_argument('--claim-kind',default='es_original');p.add_argument('--gallery',default='madrid-50m');p.add_argument('--rankings',type=Path,default=ROOT/'results/generated/f5/h11-h25-independent/rankings.json');p.add_argument('--plan',type=Path,default=ROOT/'results/generated/f5/h11-h25-independent/plan.json');p.add_argument('--inventory',type=Path,default=ROOT/'results/generated/mapillary/d004-buffer100m/inventory.json');p.add_argument('--output',type=Path,required=True);p.add_argument('--max-images',type=int,default=3);a=p.parse_args();rankings=json.loads(a.rankings.read_text());plan=json.loads(a.plan.read_text());inventory=json.loads(a.inventory.read_text());reject_ground_truth(rankings,path='rankings');reject_ground_truth(plan,path='plan');rows=[r for r in rankings['rows'] if r['query_id']==a.query_id and r['kind']==a.kind and r['gallery_id']==a.gallery];controls=[r for r in plan['controls'] if r['query_id']==a.query_id and r['kind']==a.kind];claim_controls=[r for r in plan['controls'] if r['query_id']==a.query_id and r['kind']==a.claim_kind]
 if len(rows)!=1 or len(controls)!=1 or len(claim_controls)!=1:raise ValueError('ranking/control no únicos')
 baseline=rows[0]['results'];candidates=[{k:r[k] for k in ('candidate_id','latitude','longitude')} for r in baseline];views=plan_multiview_associations(candidates,inventory['images'],max_images_per_candidate=a.max_images);rank={r['candidate_id']:r['rank'] for r in baseline};associations=[{**r,'baseline_rank':rank[r['candidate_id']],'orientation_comparable':False,'orientation_comparability_method':'not_established'} for r in views['associations']];claims=compile_atomic_claims(claim_controls[0]['text'],[]);doc={'schema_version':'1.0','contract_version':'visual-query-fixture-v1','fixture_role':'technical_multquery_no_gt','query_key':'visual-query-'+hashlib.sha256((a.query_id+controls[0]['text_sha256']+claim_controls[0]['text_sha256']).encode()).hexdigest(),'inputs':{'rankings_sha256':digest(a.rankings),'plan_sha256':digest(a.plan),'inventory_sha256':digest(a.inventory)},'baseline':{'query_id':a.query_id,'kind':a.kind,'gallery_id':a.gallery,'text':controls[0]['text'],'text_sha256':controls[0]['text_sha256'],'results':baseline},'claim_source':{'kind':a.claim_kind,'text':claim_controls[0]['text'],'text_sha256':claim_controls[0]['text_sha256']},'claims':claims,'associations':associations,'coverage':{'candidates':10,'covered':views['covered_candidate_count'],'associations':len(associations),'assets':views['unique_asset_count']},'policy':views['policy'],'limitations':['technical_fixture_not_human_reviewed','no_vlm_execution_authorized_by_fixture','ground_truth_not_loaded']};doc['fixture_id']='visual-query-fixture-sha256-'+hashlib.sha256(canonical_bytes(doc)).hexdigest();a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_bytes(canonical_bytes(doc)+b'\n');print(json.dumps({'query_id':a.query_id,'fixture_id':doc['fixture_id'],'claims':len(claims['claims']),**doc['coverage']},sort_keys=True));return 0
if __name__=='__main__':raise SystemExit(main())
